const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(new Cesium.OpenStreetMapImageryProvider({
    url: 'https://tile.openstreetmap.org/',
    maximumLevel: 18
  })),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false
}));

viewer.scene.globe.enableLighting = false;

// Mark the Eiffel Tower location for visual reference
viewer.entities.add({
  position: Cesium.Cartesian3.fromDegrees(2.2945, 48.8584, 0.0),
  point: {
    pixelSize: 12,
    color: Cesium.Color.RED,
    outlineColor: Cesium.Color.WHITE,
    outlineWidth: 2,
    heightReference: Cesium.HeightReference.CLAMP_TO_GROUND
  },
  label: {
    text: 'Eiffel Tower',
    font: '14pt sans-serif',
    fillColor: Cesium.Color.WHITE,
    outlineColor: Cesium.Color.BLACK,
    outlineWidth: 2,
    style: Cesium.LabelStyle.FILL_AND_OUTLINE,
    verticalOrigin: Cesium.VerticalOrigin.BOTTOM,
    pixelOffset: new Cesium.Cartesian2(0, -16),
    heightReference: Cesium.HeightReference.CLAMP_TO_GROUND
  }
});

// Target the mid-section of the tower (~150 m) so the structure fills the frame
// rather than just looking at the base footprint.
const target = Cesium.Cartesian3.fromDegrees(2.2945, 48.8584, 150.0);

// Heading 180° = camera faces south → camera is positioned north of the target.
// This puts the Champ de Mars (which extends south of the tower) visible beyond it.
viewer.camera.lookAt(
  target,
  new Cesium.HeadingPitchRange(
    Cesium.Math.toRadians(180.0),  // face south → camera north of tower
    Cesium.Math.toRadians(-25.0),  // 25° downward angle
    1000.0                          // 1000 m standoff distance
  )
);
```

**What this does:**

- **Heading 180°** — the camera faces south, placing it to the north of the Eiffel Tower. The Champ de Mars park stretches southward behind the tower into the background.
- **Pitch −25°** — a gentle downward angle that keeps the tower prominent vertically while showing enough ground to see the park layout.
- **Target altitude 150 m** — locks onto the tower's mid-section rather than its base, so the structure fills the frame vertically rather than appearing to float at the bottom.
- **Range 1,000 m** — close enough for the tower to dominate the view, far enough to show its full height and the surrounding Champ de Mars.

